static const float C_VAL = 10.244771f;

inline float c_average_path_length(int n) {
  if (n <= 1) return 0.0f;
  return 2.0f * (logf(n - 1) + 0.5772156649f) - 2.0f * (n - 1) / n;
}

inline float path_length(const float* sample, int tree_idx) {
  int node = TREE_OFFSET[tree_idx];
  float depth = 0.0f;
  while (TREE_LEFT[node] != TREE_RIGHT[node]) {
    int feat = TREE_FEATURE[node];
    float thresh = TREE_THRESHOLD[node];
    if (sample[feat] <= thresh) {
      node = TREE_LEFT[node] + TREE_OFFSET[tree_idx];
    } else {
      node = TREE_RIGHT[node] + TREE_OFFSET[tree_idx];
    }
    depth += 1.0f;
  }
  depth += c_average_path_length(TREE_LEFT[node]); // leaf size approximation
  return depth;
}

float predict_anomaly(const float* features) {
  float avg_depth = 0.0f;
  for (int i = 0; i < N_ESTIMATORS; ++i) {
    avg_depth += path_length(features, i);
  }
  avg_depth /= N_ESTIMATORS;
  float score = powf(2.0f, -avg_depth / C_VAL);
  return score;
}

